import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext'; // Assuming this path is correct

const AdminDashboard = () => {
  // User Management State
  const [users, setUsers] = useState([]);
  const [usersLoading, setUsersLoading] = useState(true); // Renamed from loading

  // Inventory Management State
  const [inventoryItems, setInventoryItems] = useState([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');
  const [newItemQuantity, setNewItemQuantity] = useState('');
  const [inventoryLoading, setInventoryLoading] = useState(true);
  const [error, setError] = useState(null); // General error state

  const { currentUser, logout } = useAuth();

  // Fetch Users and Inventory on component mount
  useEffect(() => {
    fetchUsers();
    fetchInventory();
  }, []);

  // --- User Management Functions ---
  const fetchUsers = async () => {
    setUsersLoading(true);
    setError(null); // Clear previous errors
    try {
      // Assuming your API endpoint for fetching users is correct
      const response = await axios.get('/api/admin/users'); // Changed to relative path, adjust if needed
      setUsers(response.data.data);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to fetch users. Please try again.'); // Set error message
    } finally {
      setUsersLoading(false);
    }
  };

  const updateUserRole = async (userId, newRole) => {
    try {
      await axios.put(`/api/admin/users/${userId}/role`, { // Changed to relative path
        role: newRole
      });
      fetchUsers(); // Refresh the user list
    } catch (err) {
      console.error('Error updating user role:', err);
      setError('Failed to update user role.');
    }
  };

  const deleteUser = async (userId) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      try {
        await axios.delete(`/api/admin/users/${userId}`); // Changed to relative path
        fetchUsers(); // Refresh the user list
      } catch (err) {
        console.error('Error deleting user:', err);
        setError('Failed to delete user.');
      }
    }
  };

  // --- Inventory Management Functions ---
  const fetchInventory = async () => {
    setInventoryLoading(true);
    setError(null); // Clear previous errors
    try {
      // Assuming your API endpoint for fetching inventory is /api/admin/inventory
      const response = await axios.get('/api/admin/inventory'); // Changed to relative path
      setInventoryItems(response.data.data);
    } catch (err) {
      console.error('Error fetching inventory:', err);
      setError('Failed to fetch inventory. Please try again.');
    } finally {
      setInventoryLoading(false);
    }
  };

  const addItem = async (e) => {
    e.preventDefault(); // Prevent default form submission
    if (!newItemName || !newItemPrice || !newItemQuantity) {
      alert('Please fill in all fields.');
      return;
    }

    // Basic validation for price and quantity
    const price = parseFloat(newItemPrice);
    const quantity = parseInt(newItemQuantity, 10);

    if (isNaN(price) || price < 0) {
      alert('Please enter a valid price (non-negative number).');
      return;
    }
    if (isNaN(quantity) || quantity < 0) {
      alert('Please enter a valid quantity (non-negative integer).');
      return;
    }

    try {
      // Assuming your API endpoint for adding inventory is /api/admin/inventory (POST)
      const response = await axios.post('/api/admin/inventory', { // Changed to relative path
        name: newItemName,
        price: price,
        quantity: quantity,
      });
      // After successfully adding, refresh the inventory list
      fetchInventory();
      // Clear the form fields
      setNewItemName('');
      setNewItemPrice('');
      setNewItemQuantity('');
      alert('Item added successfully!'); // User feedback
    } catch (err) {
      console.error('Error adding item:', err);
      setError('Failed to add item.');
    }
  };

  // Overall loading state: show loading if either users or inventory is loading
  if (usersLoading || inventoryLoading) {
    return <div className="flex justify-center items-center h-screen">Loading...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navbar */}
      <nav className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-red-600">Admin Dashboard</h1>
            </div>
            <div className="flex items-center space-x-4">
              {/* Display current user's username if available */}
              <span className="text-gray-700">Welcome, Admin {currentUser?.username || 'User'}</span>
              <button
                onClick={logout}
                className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md text-sm font-medium"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-6 sm:px-0">

          {/* Display Errors if any */}
          {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-8" role="alert">
              <strong className="font-bold">Error:</strong>
              <span className="block sm:inline"> {error}</span>
              <span className="absolute top-0 bottom-0 right-0 px-4 py-3">
                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                  <svg className="fill-current h-6 w-6 text-red-500" role="button" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><title>Close</title><path d="M14.348 14.849c-0.469 0.469-1.229 0.469-1.697 0L10 11.819l-2.651 3.029c-0.469 0.469-1.229 0.469-1.697 0-0.469-0.469-0.469-1.229 0-1.697l2.651-3.029L5.651 5.651c-0.469-0.469-0.469-1.229 0-1.697c0.469-0.469 1.229-0.469 1.697 0L10 8.181l2.651-3.029c0.469-0.469 1.229-0.469 1.697 0c0.469 0.469 0.469 1.229 0 1.697L11.819 10l3.029 2.651c0.469 0.469 0.469 1.229 0 1.697z"/></svg>
                </button>
              </span>
            </div>
          )}

          {/* Stats Overview */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            {/* Total Users Card */}
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="h-10 w-10 bg-blue-500 rounded-full flex items-center justify-center">
                      <span className="text-white">👥</span>
                    </div>
                  </div>
                  <div className="ml-5 w-0 flex-1">
                    <dl>
                      <dt className="text-sm font-medium text-gray-500 truncate">
                        Total Users
                      </dt>
                      <dd className="text-2xl font-bold text-gray-900">
                        {users.length}
                      </dd>
                    </dl>
                  </div>
                </div>
              </div>
            </div>
            {/* Total Inventory Items Card */}
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="h-10 w-10 bg-green-500 rounded-full flex items-center justify-center">
                      <span className="text-white">📦</span> {/* Inventory icon */}
                    </div>
                  </div>
                  <div className="ml-5 w-0 flex-1">
                    <dl>
                      <dt className="text-sm font-medium text-gray-500 truncate">
                        Total Inventory Items
                      </dt>
                      <dd className="text-2xl font-bold text-gray-900">
                        {inventoryItems.length}
                      </dd>
                    </dl>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Add New Item Form */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900">
                Add New Inventory Item
              </h3>
              <form onSubmit={addItem} className="mt-5 grid grid-cols-1 gap-y-6 sm:grid-cols-3">
                <div>
                  <label htmlFor="itemName" className="block text-sm font-medium text-gray-700">
                    Item Name
                  </label>
                  <div className="mt-1">
                    <input
                      type="text"
                      id="itemName"
                      value={newItemName}
                      onChange={(e) => setNewItemName(e.target.value)}
                      required
                      className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2"
                      placeholder="e.g., Laptop"
                    />
                  </div>
                </div>
                <div>
                  <label htmlFor="itemPrice" className="block text-sm font-medium text-gray-700">
                    Price
                  </label>
                  <div className="mt-1">
                    <input
                      type="number"
                      id="itemPrice"
                      value={newItemPrice}
                      onChange={(e) => setNewItemPrice(e.target.value)}
                      required
                      min="0"
                      step="0.01"
                      className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2"
                      placeholder="e.g., 1200.50"
                    />
                  </div>
                </div>
                <div>
                  <label htmlFor="itemQuantity" className="block text-sm font-medium text-gray-700">
                    Quantity
                  </label>
                  <div className="mt-1">
                    <input
                      type="number"
                      id="itemQuantity"
                      value={newItemQuantity}
                      onChange={(e) => setNewItemQuantity(e.target.value)}
                      required
                      min="0"
                      className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2"
                      placeholder="e.g., 50"
                    />
                  </div>
                </div>
                <div className="sm:col-span-3 flex items-end">
                  <button
                    type="submit"
                    className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
                  >
                    Add Item
                  </button>
                </div>
              </form>
            </div>
          </div>

          {/* Users Table */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">
                Users
              </h3>
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Name
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Email
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Role
                    </th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {users.map((user) => (
                    <tr key={user._id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {user.name}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {user.email}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        <select
                          value={user.role}
                          onChange={(e) => updateUserRole(user._id, e.target.value)}
                          className="border rounded px-2 py-1 text-sm"
                        >
                          <option value="user">User</option>
                          <option value="admin">Admin</option>
                        </select>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                        <button
                          onClick={() => deleteUser(user._id)}
                          className="text-red-600 hover:text-red-900"
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Inventory Table */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">
                Current Inventory
              </h3>
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Item Name
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Price
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Quantity
                    </th>
                    {/* You can add action buttons here if needed (e.g., Edit, Delete) */}
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {inventoryItems.map((item) => (
                    <tr key={item._id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {item.name}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        ${item.price.toFixed(2)} {/* Format price to 2 decimal places */}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {item.quantity}
                      </td>
                      {/* Add cells for actions if needed */}
                    </tr>
                  ))}
                </tbody>
              </table>
              {/* Display message if inventory is empty */}
              {inventoryItems.length === 0 && !inventoryLoading && (
                <p className="text-center py-4 text-gray-500">No items in inventory yet.</p>
              )}
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
